using System.Collections.Generic; using System.IO; using System.Text.Json; using Domain.Entities; using Domain.Interfaces; namespace Infrastructure.Repositories { public class JsonPhotoRepository : IPhotoRepository { private readonly string _filePath; public JsonPhotoRepository(string filePath) { _filePath = filePath; } public void Add(Photo photo) { var photos = new List<Photo>(GetAll()); photos.Add(photo); var json = JsonSerializer.Serialize(photos, new JsonSerializerOptions { WriteIndented = true }); File.WriteAllText(_filePath, json); } public IEnumerable<Photo> GetAll() { if (!File.Exists(_filePath)) return new List<Photo>(); var json = File.ReadAllText(_filePath); return JsonSerializer.Deserialize<List<Photo>>(json) ?? new List<Photo>(); } } }
